"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('upper', 40), ('lower', 11), ('lower', 28), ('hill', 42), ('lower', 26), ('hill', 48), ('river', 36)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

