"""Peak weighted kilos. Rate lookups are billed, so the peak is remembered."""
import rates


class HarvestTracker:
    def __init__(self):
        self._harvests = []
        self._peak = None

    def record(self, harvest):
        """Record one harvest."""
        self._harvests.append(harvest)

    def peak(self):
        """Return the highest kilos times rate seen so far, or 0 when nothing is recorded.

        The result is remembered: asking again without recording anything makes no new rate lookups.
        """
        if self._peak is None:
            self._peak = max((x.kilos * rates.rate_for(x.field) for x in self._harvests), default=0)
        return self._peak


def largest_kilos(harvests):
    """Return the largest kilos, or None when there are no harvests."""
    values = [x.kilos for x in harvests]
    return max(values) if values else None
